'use strict';

/* ==========================================================================
   1. PERSONALIZATION: edit everything in this block, nothing else is needed
   ========================================================================== */
const CONFIG = {
  // Her name or nickname. Used in the letter greeting.
  girlfriendName: 'HER NAME',

  // Your name or nickname. Used for the page title and as a fallback signature.
  myName: 'Spidey',

  // Stage 1 texts
  greeting: 'hi baby 🌷',
  introText: 'eto ang hinanda ko para sayo, pero bago yon buoin mo muna to hehehe',
  howToPlay: 'Tap a piece, tas tap another piece to pagpalitin mo sila. Pag nalagay mona magkakaron ng check mark.',
  puzzleCompleteMessage: 'wow galing hahaha!',

  // Stage 2 texts
  questionText: 'Mahal moba talaga ko?',
  yesLabel: 'Yes',
  noLabel: 'No',

  // Stage 5: the letter.
  // {name} is replaced by girlfriendName.
  letterSalutation: 'Dear elle,',

  // Replace the placeholder between the backticks with your own words.
  // Blank lines start a new paragraph. Single line breaks are kept as line breaks.
  // Your text is shown exactly as you write it. Use a backtick-free message
  // (avoid the ` character and the two-character sequence ${ inside it).
  loveLetter: `hi elle, happy monthsary!!, isang buwan na tayo😗, isang buwan ng di pagkakaintindihan, isang buwan ng pag aaway, isang buwan ng pag uunawaan at isang buwan ng pag mamahalan, to many more months and years to come hshshs. Maraming salamat bi, sa pag aalaga, pag aalala, pangangaral, pag mamahal, at pag unawa. I love you bi, maraming samalat sa isang buwan and claiming to next months and years with u, sorry at may pasok ang bida kanina, sana maunawaan mo, i love you!!!!`,

  closing: 'With all my love,',

  // Signature under the letter (leave '' to use myName instead).
  signature: 'Spidey boyyyyy',

  // Optional line shown under the signature, for example a P.S. Leave '' to hide it.
  finalMessage: 'mwaaa',

  // Local audio file. See README.md for how to add it.
  musicPath: 'assets/audio/mp3.mp3',
  musicVolume: 0.5   // 0 to 1
};

/* ==========================================================================
   2. PUZZLE PICTURE: the tulip bouquet (same image as assets/images/tulip-puzzle.jpg)
   It is embedded here so the puzzle never depends on a file loading.
   To use a different picture, replace the data below or set TULIP_URL to a file path.
   ========================================================================== */
const TULIP_URL = 'data:image/jpeg;base64,';

/* ==========================================================================
   3. SMALL HELPERS
   ========================================================================== */
const REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const FADE_MS = REDUCED ? 50 : 650;        // matches the CSS stage fade
const REVEAL_MS = REDUCED ? 1800 : 7000;   // length of the tulip bloom scene
const GRID = 3;                            // puzzle is GRID x GRID
const PIECES = GRID * GRID;

const $ = (id) => document.getElementById(id);
const rand = (min, max) => min + Math.random() * (max - min);
const clamp = (v, min, max) => Math.min(Math.max(v, min), max);

const els = {};   // filled in by cacheElements()

function cacheElements() {
  ['stage-puzzle', 'stage-question', 'stage-reveal', 'stage-scroll', 'stage-letter',
   'puzzleBoard', 'previewImg', 'progressTrack', 'progressFill', 'progressText',
   'puzzleBanner', 'puzzleStatus', 'questionCard', 'yesBtn', 'noBtn', 'noSlot',
   'revealPetals', 'revealScene', 'revealStatus', 'scroll', 'seal', 'scrollHint',
   'letter', 'letterGreeting', 'letterBody', 'letterClosing', 'letterSignature',
   'letterFinal', 'replayBtn', 'musicBtn', 'musicNote', 'ambient', 'fxLayer'
  ].forEach((id) => { els[id] = $(id); });
}

/* Copies CONFIG text into every element marked with data-cfg="key". */
function applyConfig() {
  document.querySelectorAll('[data-cfg]').forEach((node) => {
    const key = node.getAttribute('data-cfg');
    if (typeof CONFIG[key] === 'string') node.textContent = CONFIG[key];
  });
  document.title = 'A letter from ' + CONFIG.myName;
  els.previewImg.src = TULIP_URL;
  els.puzzleBoard.style.setProperty('--tulip', 'url("' + TULIP_URL + '")');
}

/* ==========================================================================
   4. STATE MACHINE
   The experience always moves in this exact order, one step at a time.
   ========================================================================== */
const STATE_ORDER = ['puzzle', 'continueQuestion', 'tulipReveal', 'closedScroll', 'openingScroll', 'loveLetter'];

const state = { current: null, locked: false };
let STAGE_EL = {};   // state name -> section element
let ENTER = {};      // state name -> function that starts that stage

/* A "scope" holds the event listeners and timers of the current stage.
   When a stage ends, everything in its scope is cleaned up automatically. */
let scope = null;

function startScope() {
  scope = { ac: new AbortController(), timers: new Set() };
}

function endScope() {
  if (!scope) return;
  scope.ac.abort();                       // removes every listener added with on()
  scope.timers.forEach(clearTimeout);     // cancels every timer added with later()
  scope.timers.clear();
  scope = null;
}

/* Timer that is cancelled automatically when the stage ends. */
function later(fn, ms) {
  const s = scope;
  if (!s) return null;
  const id = setTimeout(() => {
    s.timers.delete(id);
    if (scope === s) fn();
  }, ms);
  s.timers.add(id);
  return id;
}

/* Listener that is removed automatically when the stage ends. */
function on(target, type, handler, options) {
  target.addEventListener(type, handler, Object.assign({}, options, { signal: scope.ac.signal }));
}

/**
 * Moves to the next stage. Only the very next state in STATE_ORDER is allowed,
 * and nothing can start while another transition is running. This is what
 * prevents skipping, duplicate transitions and rapid double-click problems.
 */
function goTo(next) {
  const fromIndex = STATE_ORDER.indexOf(state.current);
  const nextIndex = STATE_ORDER.indexOf(next);
  if (nextIndex !== fromIndex + 1 || state.locked) return false;

  state.locked = true;
  endScope();

  const fromEl = state.current ? STAGE_EL[state.current] : null;
  const toEl = STAGE_EL[next];

  const show = () => {
    state.current = next;
    document.body.dataset.state = next;

    if (fromEl && fromEl !== toEl) {
      fromEl.classList.remove('is-active', 'is-visible');
      fromEl.setAttribute('inert', '');
    }
    if (fromEl !== toEl) {
      toEl.removeAttribute('inert');
      toEl.classList.add('is-active');
      void toEl.offsetWidth;              // makes the fade-in transition run
      toEl.classList.add('is-visible');
      window.scrollTo(0, 0);
    }

    startScope();
    try {
      ENTER[next]();
    } catch (err) {
      console.error('Stage "' + next + '" had a problem:', err);
    }
    state.locked = false;
  };

  if (fromEl && fromEl !== toEl) {
    fromEl.classList.remove('is-visible');   // fade out first
    setTimeout(show, FADE_MS);               // plain timer: does not depend on transitionend
  } else {
    show();
  }
  return true;
}

/* ==========================================================================
   5. EFFECTS: petals and sparkles
   ========================================================================== */

/** Floating petals. loop=true makes calm, endless background petals. */
function spawnPetals(layer, count, opts) {
  const o = Object.assign({ loop: false, delayMax: 2, durMin: 7, durMax: 12, opacity: 0.8 }, opts);
  for (let i = 0; i < count; i++) {
    const petal = document.createElement('span');
    const dur = rand(o.durMin, o.durMax);
    const delay = o.loop ? -rand(0, o.durMax) : rand(0, o.delayMax);
    petal.className = 'petal' + (Math.random() > 0.5 ? ' petal--b' : '');
    petal.style.left = rand(0, 100) + '%';
    petal.style.width = rand(10, 18) + 'px';
    petal.style.height = rand(13, 22) + 'px';
    petal.style.setProperty('--dx', rand(-18, 18) + 'vw');
    petal.style.setProperty('--rot', rand(180, 540) + 'deg');
    petal.style.setProperty('--o', String(o.opacity));
    petal.style.animationDuration = dur + 's';
    petal.style.animationDelay = delay + 's';
    petal.style.animationIterationCount = o.loop ? 'infinite' : '1';
    layer.appendChild(petal);
    if (!o.loop) {
      petal.addEventListener('animationend', () => petal.remove(), { once: true });
      setTimeout(() => petal.remove(), (dur + delay) * 1000 + 800);   // fallback
    }
  }
}

/** Small burst of sparkles from the middle of an element. */
function burstSparkles(origin, count) {
  const rect = origin.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const colors = ['#FFFFFF', '#F3B6C8', '#D96C91', '#FFF8F5'];
  for (let i = 0; i < count; i++) {
    const spark = document.createElement('span');
    const angle = rand(0, Math.PI * 2);
    const dist = rand(60, Math.max(120, rect.width * 0.7));
    spark.className = 'spark';
    spark.style.left = cx + 'px';
    spark.style.top = cy + 'px';
    spark.style.setProperty('--dx', Math.cos(angle) * dist + 'px');
    spark.style.setProperty('--dy', Math.sin(angle) * dist + 'px');
    spark.style.setProperty('--c', colors[i % colors.length]);
    spark.style.animationDelay = rand(0, 0.25) + 's';
    els.fxLayer.appendChild(spark);
    setTimeout(() => spark.remove(), 1600);
  }
}

/* ==========================================================================
   6. STAGE 1: THE TULIP PUZZLE
   puzzle.order[slot] = which piece currently sits in that slot.
   A piece is correct when order[slot] === slot.
   ========================================================================== */
const puzzle = { order: [], locked: new Set(), selected: null, done: false, slots: [] };

/** Random arrangement where no piece starts in its correct slot. */
function makeShuffledOrder(n) {
  const base = Array.from({ length: n }, (_, i) => i);
  let arr;
  do {
    arr = base.slice();
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  } while (arr.some((v, i) => v === i));
  return arr;
}

/** Creates the 9 slot buttons once. Each shows one ninth of the tulip picture. */
function buildBoard() {
  els.puzzleBoard.replaceChildren();
  els.puzzleBoard.classList.remove('is-solved');
  puzzle.slots = [];
  for (let slot = 0; slot < PIECES; slot++) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'piece';
    btn.dataset.slot = String(slot);
    els.puzzleBoard.appendChild(btn);
    puzzle.slots.push(btn);
    paintSlot(slot);
  }
}

/** Updates one slot to show its piece and its current state (selected, locked). */
function paintSlot(slot) {
  const btn = puzzle.slots[slot];
  const pieceId = puzzle.order[slot];
  const col = pieceId % GRID;
  const row = Math.floor(pieceId / GRID);
  const locked = puzzle.locked.has(slot);
  const selected = puzzle.selected === slot;

  btn.style.backgroundPosition = (col * 100 / (GRID - 1)) + '% ' + (row * 100 / (GRID - 1)) + '%';
  btn.classList.toggle('is-locked', locked);
  btn.classList.toggle('is-selected', selected);
  btn.setAttribute('aria-pressed', String(selected));
  btn.setAttribute('aria-disabled', String(locked));

  const where = 'Row ' + (Math.floor(slot / GRID) + 1) + ', column ' + ((slot % GRID) + 1);
  let label = where + '. ';
  if (locked) label += 'Correct piece, locked in place.';
  else if (selected) label += 'Selected. Choose another piece to swap with.';
  else label += 'Piece not in its place yet. Select it to swap.';
  btn.setAttribute('aria-label', label);
}

/** Restarts a CSS animation class on an element, then removes it. */
function flashClass(el, cls, ms) {
  el.classList.remove(cls);
  void el.offsetWidth;
  el.classList.add(cls);
  setTimeout(() => el.classList.remove(cls), ms);
}

function updateProgress() {
  const n = puzzle.locked.size;
  els.progressFill.style.width = (n / PIECES * 100) + '%';
  els.progressTrack.setAttribute('aria-valuenow', String(n));
  els.progressText.textContent = n + ' of ' + PIECES + ' pieces in place';
}

/**
 * Click-to-select, click-to-swap. Works the same with a finger or a mouse.
 * Locked (correct) pieces cannot be selected, so an incorrect placement is
 * never counted as correct and finished pieces can't be undone by accident.
 */
function onPieceClick(slot) {
  if (state.current !== 'puzzle' || state.locked || puzzle.done) return;
  if (puzzle.locked.has(slot)) return;

  if (puzzle.selected === null) {                 // first tap: select
    puzzle.selected = slot;
    paintSlot(slot);
    els.puzzleStatus.textContent = 'Piece selected. Choose another piece to swap with.';
    return;
  }
  if (puzzle.selected === slot) {                 // same piece again: deselect
    puzzle.selected = null;
    paintSlot(slot);
    els.puzzleStatus.textContent = 'Selection cleared.';
    return;
  }

  const a = puzzle.selected;                      // second tap: swap
  const b = slot;
  puzzle.selected = null;
  [puzzle.order[a], puzzle.order[b]] = [puzzle.order[b], puzzle.order[a]];

  const newlyLocked = [];
  [a, b].forEach((s) => {
    if (puzzle.order[s] === s) {
      puzzle.locked.add(s);
      newlyLocked.push(s);
    }
  });

  [a, b].forEach((s) => {
    paintSlot(s);
    flashClass(puzzle.slots[s], 'landed', 450);
  });
  newlyLocked.forEach((s) => flashClass(puzzle.slots[s], 'just-locked', 850));

  updateProgress();
  els.puzzleStatus.textContent = newlyLocked.length
    ? 'A piece clicked into place. ' + puzzle.locked.size + ' of ' + PIECES + ' in place.'
    : 'Pieces swapped.';

  if (puzzle.locked.size === PIECES) completePuzzle();
}

/** Celebration, then the question appears. */
function completePuzzle() {
  puzzle.done = true;
  els.puzzleBoard.classList.add('is-solved');
  els.puzzleBanner.textContent = CONFIG.puzzleCompleteMessage;
  els.puzzleBanner.classList.add('is-visible');
  els.puzzleStatus.textContent = CONFIG.puzzleCompleteMessage + ' The tulip is complete.';
  burstSparkles(els.puzzleBoard, 22);
  if (!REDUCED) spawnPetals(els.fxLayer, 12, { delayMax: 0.6, durMin: 3.5, durMax: 5.5 });
  later(() => goTo('continueQuestion'), REDUCED ? 900 : 2800);
}

function enterPuzzle() {
  puzzle.order = makeShuffledOrder(PIECES);
  puzzle.locked = new Set();
  puzzle.selected = null;
  puzzle.done = false;
  els.puzzleBanner.classList.remove('is-visible');
  els.puzzleBanner.textContent = '';
  buildBoard();
  updateProgress();
  on(els.puzzleBoard, 'click', (e) => {
    const btn = e.target.closest('.piece');
    if (btn) onPieceClick(Number(btn.dataset.slot));
  });
}

/* ==========================================================================
   7. STAGE 2: "DO YOU WANT TO CONTINUE?"
   ========================================================================== */
const noState = { floating: false, lastMove: 0, answered: false };
const NO_MARGIN = { top: 16, right: 16, bottom: 36, left: 16 };   // keeps the button off the screen edges

/** Visible area in which the No button may live, accounting for its own size. */
function noBounds(btn) {
  const vw = document.documentElement.clientWidth;
  const vh = window.innerHeight;
  const minX = NO_MARGIN.left;
  const minY = NO_MARGIN.top;
  return {
    vw, vh, minX, minY,
    maxX: Math.max(minX, vw - btn.offsetWidth - NO_MARGIN.right),
    maxY: Math.max(minY, vh - btn.offsetHeight - NO_MARGIN.bottom)
  };
}

function rectsOverlap(a, b, pad) {
  return a.x < b.right + pad && a.x + a.w > b.left - pad &&
         a.y < b.bottom + pad && a.y + a.h > b.top - pad;
}

/**
 * Picks a random spot fully inside the viewport that avoids the question text,
 * the Yes button and the music button, and is a good distance from where the
 * button is now (so it clearly "runs away").
 */
function pickNoPosition(btn) {
  const b = noBounds(btn);
  const w = btn.offsetWidth;
  const h = btn.offsetHeight;
  const cur = btn.getBoundingClientRect();
  const text = document.querySelector('.question-text').getBoundingClientRect();
  const yes = els.yesBtn.getBoundingClientRect();
  const music = els.musicBtn.getBoundingClientRect();
  const minTravel = Math.min(b.vw, b.vh) * 0.28;

  // yesPad = how much empty space must stay around the Yes button
  const isGood = (x, y, yesPad, needTravel) => {
    const r = { x, y, w, h };
    if (rectsOverlap(r, yes, yesPad) || rectsOverlap(r, text, 12) || rectsOverlap(r, music, 12)) return false;
    return !needTravel || Math.hypot(x - cur.left, y - cur.top) >= minTravel;
  };

  // Prefer a big gap from Yes (so a tap can never hit it by mistake); relax only on very small screens
  for (const yesPad of [96, 56, 20]) {
    for (let i = 0; i < 40; i++) {
      const x = rand(b.minX, b.maxX);
      const y = rand(b.minY, b.maxY);
      if (isGood(x, y, yesPad, true)) return { x, y };
    }
  }
  // Fallback: try a 3x3 grid of spots across the screen.
  const spots = [];
  for (let gx = 0; gx < 3; gx++) {
    for (let gy = 0; gy < 3; gy++) {
      spots.push({ x: b.minX + (b.maxX - b.minX) * gx / 2, y: b.minY + (b.maxY - b.minY) * gy / 2 });
    }
  }
  spots.sort((p, q) => Math.hypot(q.x - cur.left, q.y - cur.top) - Math.hypot(p.x - cur.left, p.y - cur.top));
  const free = spots.find((p) => isGood(p.x, p.y, 20, false));
  return free || { x: rand(b.minX, b.maxX), y: rand(b.minY, b.maxY) };
}

/** The No button politely runs away every time she tries to press it. */
function dodgeNo() {
  if (state.current !== 'continueQuestion' || noState.answered) return;
  const now = performance.now();
  if (now - noState.lastMove < 200) return;    // one press = one move (pointerdown + click)
  noState.lastMove = now;

  const btn = els.noBtn;
  if (!noState.floating) {
    // First time: lift the button out of the layout without any visual jump.
    const r = btn.getBoundingClientRect();
    els.noSlot.style.width = r.width + 'px';
    els.noSlot.style.height = r.height + 'px';
    btn.classList.add('is-floating');
    btn.style.left = r.left + 'px';
    btn.style.top = r.top + 'px';
    noState.floating = true;
    void btn.offsetWidth;
  }
  const pos = pickNoPosition(btn);
  btn.style.left = pos.x + 'px';
  btn.style.top = pos.y + 'px';
}

/** If the screen is resized or rotated, keep No inside the visible area. */
function clampNo() {
  if (!noState.floating) return;
  const btn = els.noBtn;
  const b = noBounds(btn);
  const r = btn.getBoundingClientRect();
  btn.style.transition = 'none';
  btn.style.left = clamp(r.left, b.minX, b.maxX) + 'px';
  btn.style.top = clamp(r.top, b.minY, b.maxY) + 'px';
  void btn.offsetWidth;
  btn.style.transition = '';
}

function onYes() {
  if (state.current !== 'continueQuestion' || state.locked || noState.answered) return;
  noState.answered = true;
  els.yesBtn.disabled = true;      // both buttons off so nothing can be pressed twice
  els.noBtn.disabled = true;
  els['stage-question'].classList.add('is-answered');
  later(() => goTo('tulipReveal'), REDUCED ? 100 : 750);
}

function enterQuestion() {
  noState.floating = false;
  noState.lastMove = 0;
  noState.answered = false;
  els['stage-question'].classList.remove('is-answered');
  els.noBtn.classList.remove('is-floating');
  els.noBtn.style.left = '';
  els.noBtn.style.top = '';
  els.noSlot.style.width = '';
  els.noSlot.style.height = '';
  els.yesBtn.disabled = false;
  els.noBtn.disabled = false;

  on(els.yesBtn, 'click', onYes);
  on(els.noBtn, 'pointerdown', dodgeNo);                          // moves before a finger can finish the tap
  on(els.noBtn, 'click', (e) => { e.preventDefault(); dodgeNo(); }); // keyboard (Enter/Space) too
  on(window, 'resize', clampNo);
  on(window, 'orientationchange', clampNo);
  later(() => els.yesBtn.focus({ preventScroll: true }), 700);
}

/* ==========================================================================
   8. STAGE 3: TULIP REVEAL (SVG + CSS animation)
   Each flower is built from stem, leaves and layered petals. CSS handles the
   timing: stem grows, leaves unfold, bud appears, petals open.
   ========================================================================== */
const FLOWERS = [
  // x, y = base of stem in the 400x600 scene, s = size, lean = tilt, d = start delay (seconds)
  { x: 50,  y: 604, s: 0.80, lean: -9, d: 1.8, front: 'gFrontBlush', back: 'gBackBlush' },
  { x: 352, y: 604, s: 0.85, lean: 8,  d: 2.0, front: 'gFront',      back: 'gBack' },
  { x: 112, y: 592, s: 1.05, lean: -7, d: 1.2, front: 'gFrontBlush', back: 'gBackBlush' },
  { x: 292, y: 594, s: 1.15, lean: 6,  d: 1.5, front: 'gFrontDeep',  back: 'gBackDeep' },
  { x: 200, y: 588, s: 1.55, lean: 0,  d: 0,   front: 'gFront',      back: 'gBack' }    // the main tulip, drawn last (on top)
];

function gradient(id, top, bottom) {
  return '<linearGradient id="' + id + '" x1="0" y1="0" x2="0" y2="1">' +
         '<stop offset="0" stop-color="' + top + '"/><stop offset="1" stop-color="' + bottom + '"/></linearGradient>';
}

function flowerMarkup(f) {
  return '<g transform="translate(' + f.x + ' ' + f.y + ') rotate(' + f.lean + ') scale(' + f.s + ')">' +
    '<g class="flower" style="--d:' + f.d + 's">' +
      '<path class="stem" pathLength="1" d="M0 0 C-8 -60 8 -120 0 -180"/>' +
      '<path class="leaf" d="M-2 -4 C-50 -22 -80 -72 -78 -126 C-42 -104 -10 -58 -2 -4Z"/>' +
      '<path class="leaf" d="M2 -4 C50 -20 82 -62 82 -112 C46 -92 10 -52 2 -4Z"/>' +
      '<g transform="translate(0 -180)"><g class="head">' +
        '<path class="p-left" d="M0 0 C-40 -10 -48 -60 -32 -102 C-14 -82 -2 -54 0 0Z" fill="url(#' + f.back + ')"/>' +
        '<path class="p-right" d="M0 0 C40 -10 48 -60 32 -102 C14 -82 2 -54 0 0Z" fill="url(#' + f.back + ')"/>' +
        '<path class="p-front" d="M0 6 C-44 0 -52 -56 0 -110 C52 -56 44 0 0 6Z" fill="url(#' + f.front + ')"/>' +
        '<path class="p-shine" d="M0 -90 C-22 -64 -22 -29 -8 -10"/>' +
      '</g></g>' +
    '</g></g>';
}

function buildScene() {
  els.revealScene.innerHTML =
    '<defs>' +
      gradient('gFront', '#EA93AF', '#D96C91') +
      gradient('gBack', '#CC6286', '#B84F76') +
      gradient('gFrontBlush', '#F9D3DF', '#F3B6C8') +
      gradient('gBackBlush', '#EBA3BB', '#E08BA8') +
      gradient('gFrontDeep', '#D4668B', '#B84F76') +
      gradient('gBackDeep', '#A94369', '#8F3555') +
      gradient('gLeaf', '#A9BCA1', '#91A889') +
      gradient('gGround', '#B7CBAC', '#9FB895') +
      '<radialGradient id="gGlow" cx="0.5" cy="0.5" r="0.5">' +
        '<stop offset="0" stop-color="#FFFFFF" stop-opacity="0.8"/>' +
        '<stop offset="1" stop-color="#FFFFFF" stop-opacity="0"/></radialGradient>' +
    '</defs>' +
    '<path class="ground" fill="url(#gGround)" opacity="0.55" d="M0 566 C80 546 140 580 210 566 C290 550 340 574 400 558 V600 H0Z"/>' +
    '<circle class="bloom-glow" cx="200" cy="235" r="170" fill="url(#gGlow)"/>' +
    FLOWERS.map(flowerMarkup).join('');
}

function enterReveal() {
  buildScene();
  els.revealStatus.textContent = 'A bouquet of pink tulips is blooming.';
  if (!REDUCED) {
    later(() => spawnPetals(els.revealPetals, 10, { delayMax: 2.5, durMin: 6, durMax: 9 }), 600);
    later(() => spawnPetals(els.revealPetals, 8, { delayMax: 1.5, durMin: 6, durMax: 8 }), 4200);
  }
  later(() => goTo('closedScroll'), REVEAL_MS);   // a timer, so it can never get stuck waiting for an animation event
}

/* ==========================================================================
   9. STAGE 4: THE MYSTERY SCROLL
   The wax seal shimmers and wobbles. Tapping it (or a short swipe on the
   scroll) breaks the seal and the scroll unrolls.
   ========================================================================== */
function openScroll() {
  if (state.current === 'closedScroll') goTo('openingScroll');
}

function enterClosedScroll() {
  els.scroll.classList.remove('is-cracking', 'is-open');
  els.scrollHint.classList.remove('is-visible');

  on(els.seal, 'click', openScroll);

  // Short swipe anywhere on the scroll also works
  let start = null;
  on(els.scroll, 'pointerdown', (e) => { start = { x: e.clientX, y: e.clientY }; });
  on(els.scroll, 'pointermove', (e) => {
    if (!start) return;
    if (Math.hypot(e.clientX - start.x, e.clientY - start.y) > 40) {
      start = null;
      openScroll();
    }
  });
  on(els.scroll, 'pointerup', () => { start = null; });
  on(els.scroll, 'pointercancel', () => { start = null; });

  // If she hasn't found it after a few seconds, a soft clue fades in
  later(() => els.scrollHint.classList.add('is-visible'), 7000);
}

function enterOpeningScroll() {
  els.scrollHint.classList.remove('is-visible');
  els.scroll.classList.add('is-cracking');                                  // seal breaks
  later(() => els.scroll.classList.add('is-open'), REDUCED ? 100 : 450);    // paper unrolls
  later(() => goTo('loveLetter'), REDUCED ? 800 : 3900);                    // then the letter appears
}

/* ==========================================================================
   10. STAGE 5: THE LOVE LETTER
   ========================================================================== */
const letterState = { running: false, timers: [] };

/** Builds the letter from CONFIG. Text is inserted safely as plain text. */
function buildLetter() {
  els.letterGreeting.textContent = CONFIG.letterSalutation.replace('{name}', CONFIG.girlfriendName);

  els.letterBody.replaceChildren();
  const paragraphs = String(CONFIG.loveLetter).replace(/\r\n/g, '\n').trim().split(/\n\s*\n/);
  paragraphs.forEach((text) => {
    const p = document.createElement('p');
    p.className = 'letter-paragraph reveal';
    text.split('\n').forEach((line, i) => {
      if (i > 0) p.appendChild(document.createElement('br'));   // keeps your line breaks
      p.appendChild(document.createTextNode(line.replace(/^[ \t]+/, '')));
    });
    els.letterBody.appendChild(p);
  });

  els.letterClosing.textContent = CONFIG.closing;
  els.letterSignature.textContent = CONFIG.signature || CONFIG.myName;
  els.letterFinal.textContent = CONFIG.finalMessage;
  els.letterFinal.hidden = !CONFIG.finalMessage;
}

function letterItems() {
  return Array.from(els.letter.querySelectorAll('.reveal')).filter((el) => !el.hidden);
}

function clearLetterTimers() {
  letterState.timers.forEach(clearTimeout);
  letterState.timers = [];
}

/** Fades the letter in piece by piece: greeting, body, closing, signature. */
function runLetterReveal() {
  clearLetterTimers();
  const items = letterItems();
  items.forEach((el) => el.classList.remove('visible'));
  letterState.running = true;

  const step = REDUCED ? 0 : clamp(6000 / items.length, 380, 950);
  items.forEach((el, i) => {
    const id = later(() => {
      el.classList.add('visible');
      if (i === items.length - 1) letterState.running = false;
    }, (REDUCED ? 0 : 900) + i * step);
    letterState.timers.push(id);
  });
}

/** Tapping the letter while it is appearing shows everything at once. */
function revealAllLetter() {
  clearLetterTimers();
  letterItems().forEach((el) => el.classList.add('visible'));
  letterState.running = false;
}

/** "Read it again": replays only the letter reveal, never the puzzle. */
function replayLetter() {
  if (state.current !== 'loveLetter' || letterState.running) return;
  letterState.running = true;
  letterItems().forEach((el) => el.classList.remove('visible'));
  window.scrollTo({ top: 0, behavior: REDUCED ? 'auto' : 'smooth' });
  later(runLetterReveal, REDUCED ? 0 : 500);
}

function enterLetter() {
  buildLetter();
  on(els.letter, 'click', (e) => {
    if (e.target.closest('button')) return;
    if (letterState.running) revealAllLetter();
  });
  on(els.replayBtn, 'click', replayLetter);
  music.tryAutoplay();      // the letter is the best moment to start the music
  runLetterReveal();
}

/* ==========================================================================
   11. STAGE 6: BACKGROUND MUSIC
   Browsers often block sound until the user has tapped something, so:
   - the first tap anywhere quietly "unlocks" audio (silently, no sound),
   - the music tries to start when the letter appears,
   - if the browser still refuses, the music button gently pulses so she can
     start it herself,
   - if the audio file is missing, everything else keeps working.
   ========================================================================== */
const music = {
  audio: null,
  available: true,     // false if the file is missing or can't be played
  playing: false,
  wants: false,        // true when music should be on
  userChoice: false,   // true once she has used the button herself
  unlocked: false,
  fadeTimer: null,
  noteTimer: null,

  init() {
    els.musicBtn.addEventListener('click', () => music.toggle());
    try {
      const a = new Audio();
      a.loop = true;
      a.preload = 'auto';
      a.volume = 0;
      a.addEventListener('error', () => music.markUnavailable());
      a.src = CONFIG.musicPath;
      this.audio = a;
    } catch (err) {
      this.markUnavailable();
    }

    // The very first tap anywhere unlocks audio on strict browsers (iOS Safari)
    const unlockOnce = (e) => {
      if (e.target.closest && e.target.closest('#musicBtn')) return;
      document.removeEventListener('pointerdown', unlockOnce);
      music.unlock();
    };
    document.addEventListener('pointerdown', unlockOnce);
    this.render();
  },

  markUnavailable() {
    this.available = false;
    this.playing = false;
    this.render();
  },

  /** Plays a muted sound inside a tap, which allows later playback without a tap. */
  unlock() {
    if (this.unlocked || !this.available || !this.audio) return;
    this.unlocked = true;
    try {
      this.audio.muted = true;
      const p = this.audio.play();
      if (p && p.then) {
        p.then(() => {
          if (!music.wants) { music.audio.pause(); music.audio.currentTime = 0; }
          music.audio.muted = false;
        }).catch(() => { music.audio.muted = false; });
      }
    } catch (err) {
      this.audio.muted = false;
    }
  },

  async play() {
    if (!this.audio || !this.available) return false;
    try {
      this.audio.muted = false;
      await this.audio.play();
      this.playing = true;
      this.wants = true;
      this.fadeTo(CONFIG.musicVolume, 1800);
      this.render();
      return true;
    } catch (err) {
      this.playing = false;
      this.render();
      return false;
    }
  },

  pause() {
    this.playing = false;
    this.render();
    this.fadeTo(0, 700, () => {
      if (!music.playing && music.audio) music.audio.pause();
    });
  },

  /** Smooth volume change so music never starts or stops abruptly. */
  fadeTo(target, ms, done) {
    clearInterval(this.fadeTimer);
    const a = this.audio;
    if (!a) return;
    const startVol = a.volume;
    const steps = Math.max(1, Math.round(ms / 50));
    let i = 0;
    this.fadeTimer = setInterval(() => {
      i++;
      try { a.volume = clamp(startVol + (target - startVol) * (i / steps), 0, 1); } catch (err) { /* some phones fix the volume */ }
      if (i >= steps) {
        clearInterval(music.fadeTimer);
        if (done) done();
      }
    }, 50);
  },

  async toggle() {
    this.userChoice = true;
    if (!this.available) {
      this.showNote('Music file not found. Add assets/audio/romantic-piano.mp3 (see README).');
      return;
    }
    if (this.playing) {
      this.wants = false;
      this.pause();
      return;
    }
    this.wants = true;
    const ok = await this.play();
    if (!ok) {
      if (this.audio && this.audio.error) this.markUnavailable();
      this.showNote(this.available
        ? 'The browser blocked the music. Tap the button again to start it.'
        : 'Music file not found. Add assets/audio/romantic-piano.mp3 (see README).');
    }
  },

  /** Called when the letter appears. */
  async tryAutoplay() {
    if (this.playing || !this.available) return;
    if (this.userChoice && !this.wants) return;   // she turned it off herself: respect that
    this.wants = true;
    const ok = await this.play();
    if (!ok && this.available) {
      els.musicBtn.classList.add('is-nudging');
      this.showNote('Tap the music button for a little song.');
    }
  },

  showNote(text) {
    els.musicNote.textContent = text;
    els.musicNote.classList.add('is-visible');
    clearTimeout(this.noteTimer);
    this.noteTimer = setTimeout(() => els.musicNote.classList.remove('is-visible'), 4500);
  },

  render() {
    const btn = els.musicBtn;
    btn.classList.toggle('is-playing', this.playing);
    btn.classList.toggle('is-unavailable', !this.available);
    btn.setAttribute('aria-pressed', String(this.playing));
    btn.title = !this.available ? 'Music unavailable' : (this.playing ? 'Mute music' : 'Play music');
    if (this.playing) btn.classList.remove('is-nudging');
  }
};

/* ==========================================================================
   12. START
   ========================================================================== */
function init() {
  cacheElements();

  STAGE_EL = {
    puzzle: els['stage-puzzle'],
    continueQuestion: els['stage-question'],
    tulipReveal: els['stage-reveal'],
    closedScroll: els['stage-scroll'],
    openingScroll: els['stage-scroll'],
    loveLetter: els['stage-letter']
  };
  ENTER = {
    puzzle: enterPuzzle,
    continueQuestion: enterQuestion,
    tulipReveal: enterReveal,
    closedScroll: enterClosedScroll,
    openingScroll: enterOpeningScroll,
    loveLetter: enterLetter
  };

  // Every stage starts hidden and inert; goTo() reveals them in order
  Object.values(STAGE_EL).forEach((el) => el.setAttribute('inert', ''));

  applyConfig();
  music.init();
  if (!REDUCED) spawnPetals(els.ambient, 7, { loop: true, durMin: 14, durMax: 24, opacity: 0.4 });

  goTo('puzzle');
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
